    if n <= H:
        return 1
    elif n == H + 1:
        return 2
    else:
        remaining_sand = n - H
        spots = 1
        current_height = H

        while remaining_sand > 0:
            if current_height > 0:
                if remaining_sand >= current_height:
                    remaining_sand -= current_height
                    spots += 1
                else:
                    spots += 1
                    break
            current_height -= 1

        return spots

